using System.Text.Json.Nodes;
using TouhouLastWorld;

internal sealed partial class RegressionSuite
{
    private void Scenario13()
    {
        var introGrant = new LocalIntroGrant(10, 10, Array.Empty<LocalIntroPicture>());
        Check(introReload.Dispatch("first_draw_save", arguments: new(IntroGrant: introGrant with { UnitCapacity = 1 })).Status == 409 && introReload.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]!.AsArray().Count == 1, "initial confirmation preserves pending inventory when capacity is insufficient");
        var introSaved = introReload.Dispatch("first_draw_save", arguments: new(IntroGrant: introGrant)).Body!;
        Check(introSaved["user_update"]!["unit"]!["unit_list"]!.AsArray().Count == 2 && introSaved["unit_list"]![0]!["voice_set_id"]!.GetValue<int>() == 1, "initial confirmation grants the configured template and records its voice selection");
        var introConfirmedReload = new OfflineServer(new JsonStateStore(introDirectory), seed, "offline://resources/");
        introConfirmedReload.Dispatch("game_init");
        introConfirmedReload.Dispatch("login");
        Check(introConfirmedReload.Dispatch("first_draw_save").Body!["user_update"]!["unit"]!["unit_list"]!.AsArray().Count == 2 && introConfirmedReload.Dispatch("first_draw_data", arguments: new(Text: introPublicId, IntroDefinitions: introRules)).Status == 409, "initial confirmation survives restart without duplicate grants or another draw");
        introSeed["_local_first_draw_candidate"]!["picture_ids"] = new JsonArray(JsonValue.Create(100), JsonValue.Create(100));
        var introPicturesServer = new OfflineServer(new JsonStateStore(directory + "-intro-pictures"), introSeed.ToJsonString(), "offline://resources/");
        introPicturesServer.Dispatch("game_init");
        var introPicturesId = introPicturesServer.Dispatch("login").Body!["public_id"]!.GetValue<string>();
        introPicturesServer.Dispatch("first_draw_data", arguments: new(Text: introPicturesId, IntroDefinitions: introRules with { PictureIds = new[] { 100 } }));
        Check(introPicturesServer.Dispatch("first_draw_save", arguments: new(IntroGrant: introGrant)).Status == 503, "initial confirmation rejects missing equipment definitions before granting units");
        var introPictureGrant = introPicturesServer.Dispatch("first_draw_save", arguments: new(IntroGrant: introGrant with { Pictures = new[] { new LocalIntroPicture(100, 1, 2, 3) } })).Body!;
        Check(introPictureGrant["user_update"]!["picture"]!["picture_list"]!.AsArray().Count == 2 && introPictureGrant["picture_list"]!.AsArray().Count == 1 && introPictureGrant["user_update"]!["picture"]!["picture_list"]!.AsArray().Select(row => row!["user_picture_id"]!.GetValue<long>()).Distinct().Count() == 2, "initial confirmation creates distinct equipment and a single album entry");
        Console.WriteLine("Passed 5 initial confirmation checks.");
        Check(server.Dispatch("tutorial_first_gacha_do").Status == 409, "tutorial inventory refuses an unconfirmed initial selection");
        var tutorialSnapshot = introConfirmedReload.Dispatch("tutorial_first_gacha_do").Body!["user"]!;
        Check(tutorialSnapshot["unit"]!["unit_list"]!.AsArray().Count == 2, "tutorial inventory returns the already granted roster");
        tutorialSnapshot["unit"]!["unit_list"]!.AsArray().Clear();
        Check(introConfirmedReload.Dispatch("tutorial_first_gacha_do").Body!["user"]!["unit"]!["unit_list"]!.AsArray().Count == 2, "tutorial inventory does not mutate or duplicate the saved roster");
        Console.WriteLine("Passed 3 tutorial inventory checks.");
        Check(server.Dispatch("tutorial_first_gacha_confirm").Status == 409, "tutorial confirmation requires previously confirmed inventory");
        var tutorialRestore = introConfirmedReload.Dispatch("tutorial_first_gacha_confirm").Body!["user_update"]!;
        Check(tutorialRestore["unit"]!["unit_list"]!.AsArray().Count == 2 && tutorialRestore["team"]!["team_list"]!.AsArray().Count == 1 && tutorialRestore["album"]!["unit_list"]!.AsArray().Count == 1 && tutorialRestore["home_unit_info"] is not null, "tutorial confirmation restores roster, teams, album and home state cleared by the native request");
        Check(introConfirmedReload.Dispatch("tutorial_first_gacha_confirm").Body!["user_update"]!["unit"]!["unit_list"]!.AsArray().Count == 2, "tutorial confirmation does not grant additional inventory on repeated calls");
        Console.WriteLine("Passed 3 tutorial restoration checks.");
        var historySeed = JsonNode.Parse(seed)!;
        historySeed["_local_history_teams"] = new JsonArray(new JsonObject { ["kind"] = 1, ["uniq_id1"] = 10, ["uniq_id2"] = 2, ["type"] = 0, ["player_id"] = "local-history", ["units"] = new JsonArray(new JsonObject { ["unit_info"] = historySeed["unit"]!["unit_list"]![0]!.DeepClone() }) });
        var historyServer = new OfflineServer(new JsonStateStore(directory + "-history-details"), historySeed.ToJsonString(), "offline://resources/");
        historyServer.Dispatch("game_init");
        historyServer.Dispatch("login");
        var historyQuery = new LocalHistoryQuery(1, 10, 2, 0, "local-history");
        historyDefinitions = new LocalHistoryDefinitions(new[] { 1001 }, new() { [100101] = 1001 }, Array.Empty<int>());
        Check(historyServer.Dispatch("get_clear_history_teaminfo", arguments: new(HistoryQuery: historyQuery with { SecondId = 3 }, HistoryDefinitions: historyDefinitions)).Status == 404 && historyServer.Dispatch("get_clear_history_teaminfo", arguments: new(HistoryQuery: historyQuery, HistoryDefinitions: historyDefinitions with { Costumes = new() })).Status == 503, "history details require an exact query match and available costume definition");
        var historyReply = historyServer.Dispatch("get_clear_history_teaminfo", arguments: new(HistoryQuery: historyQuery, HistoryDefinitions: historyDefinitions)).Body!;
        Check(historyReply["units"]!.AsArray().Count == 1 && historyReply["units"]![0]!["unit_info"]!["unit_id"]!.GetValue<int>() == 1001, "history details return the stored unit snapshot");
        historyReply["units"]!.AsArray().Clear();
        Check(historyServer.Dispatch("get_clear_history_teaminfo", arguments: new(HistoryQuery: historyQuery, HistoryDefinitions: historyDefinitions)).Body!["units"]!.AsArray().Count == 1, "history detail responses are independent snapshots");
        Console.WriteLine("Passed 3 history detail checks.");
        var unitRecycleSeed = JsonNode.Parse(seed)!;
        var recyclableUnit = unitRecycleSeed["unit"]!["unit_list"]![0]!.DeepClone();
        recyclableUnit["user_unit_id"] = 2L;
        unitRecycleSeed["unit"]!["unit_list"]!.AsArray().Add(recyclableUnit);
        unitRecycleSeed["picture"]!["picture_list"]!.AsArray().Add(new JsonObject { ["user_picture_id"] = 1L, ["picture_id"] = 100, ["equip_user_unit_id"] = 2L });
        var unitRecycleDirectory = directory + "-unit-recycle";
        var unitRecycleServer = new OfflineServer(new JsonStateStore(unitRecycleDirectory), unitRecycleSeed.ToJsonString(), "offline://resources/");
        unitRecycleServer.Dispatch("game_init");
        unitRecycleServer.Dispatch("login");
        var unitRecycleEntry = new LocalUnitRecycleEntry(2, 1001, 1, 0, new[] { new LocalRecycleGain(3, 0, 100), new LocalRecycleGain(2, 0, 10), new LocalRecycleGain(5, 0, 2), new LocalRecycleGain(12, 99990, 3) });
        var unitRecycleRule = new LocalUnitRecycle(new[] { unitRecycleEntry }, 10000, 1000, 100);
        Check(unitRecycleServer.Dispatch("unit_recycle", arguments: new(Ids: new[] { 2L, 2L }, UnitRecycle: unitRecycleRule)).Status == 400 && unitRecycleServer.Dispatch("unit_recycle", arguments: new(Ids: new[] { 1L }, UnitRecycle: unitRecycleRule with { Entries = new[] { unitRecycleEntry with { Id = 1 } } })).Status == 409, "unit recycle rejects duplicates and assigned units");
        Check(unitRecycleServer.Dispatch("unit_recycle", arguments: new(Ids: new[] { 2L }, UnitRecycle: unitRecycleRule with { ItemMax = 2 })).Status == 409 && unitRecycleServer.Dispatch("login").Body!["user"]!["gold"]!.GetValue<int>() == 5000 && unitRecycleServer.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]!.AsArray().Count == 2, "unit recycle rolls back earlier rewards when a later reward exceeds capacity");
        unitRecycleServer.Dispatch("unit_protection", arguments: new(2, 1));
        Check(unitRecycleServer.Dispatch("unit_recycle", arguments: new(Ids: new[] { 2L }, UnitRecycle: unitRecycleRule)).Status == 409, "unit recycle preserves protected units");
        unitRecycleServer.Dispatch("unit_protection", arguments: new(2, 0));
        var unitRecycled = unitRecycleServer.Dispatch("unit_recycle", arguments: new(Ids: new[] { 2L }, UnitRecycle: unitRecycleRule)).Body!;
        Check(unitRecycled["remove_user_unit_id_list"]![0]!.GetValue<long>() == 2 && unitRecycled["gain_object_list"]!.AsArray().Count == 4 && unitRecycled["user_update"]!["phantasm_point"]!["points"]!.GetValue<int>() == 110 && unitRecycled["user_update"]!["piece"]!.GetValue<int>() == 2 && unitRecycled["user_update"]!["picture"]!["picture_list"]![0]!["equip_user_unit_id"]!.GetValue<long>() == 0, "unit recycle grants configured rewards and releases equipment");
        var unitRecycleReload = new OfflineServer(new JsonStateStore(unitRecycleDirectory), seed, "offline://resources/");
        unitRecycleReload.Dispatch("game_init");
        unitRecycleReload.Dispatch("login");
        var newUnitAfterRecycle = unitRecycleReload.Dispatch("gacha_do", count: 1).Body!["gacha_drop_list"]![0]!["unique_id"]!.GetValue<long>();
        Check(newUnitAfterRecycle == 3 && unitRecycleReload.Dispatch("unit_recycle", arguments: new(Ids: new[] { 2L }, UnitRecycle: unitRecycleRule)).Status == 404, "recycled unit identifiers are not reused after restart and stale retries cannot remove a new unit");
        Console.WriteLine("Passed 5 unit recycle checks.");
        var dispatchEndSeed = JsonNode.Parse(seed)!;
        dispatchEndSeed["dispatch"]!["dispatch_list"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 90L, ["dispatch_id"] = 10, ["end_time"] = "2000-01-01 00:00:00", ["user_unit_id_list"] = new JsonArray(JsonValue.Create(1L)) });
        dispatchEndSeed["_local_dispatch_offers"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 90L, ["dispatch_id"] = 10 });
        dispatchEndSeed["_local_dispatch_settlements"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 90L, ["dispatch_id"] = 10, ["result"] = new JsonArray(new JsonObject { ["user_unit_id"] = 1L, ["dispatch_memo_id"] = 7, ["performance"] = 1 }), ["reward"] = new JsonArray(new JsonObject { ["object_type"] = 3, ["object_id"] = 0, ["amount"] = 100 }, new JsonObject { ["object_type"] = 12, ["object_id"] = 99990, ["amount"] = 3 }) });
        var dispatchEndDirectory = directory + "-dispatch-end";
        var dispatchEndServer = new OfflineServer(new JsonStateStore(dispatchEndDirectory), dispatchEndSeed.ToJsonString(), "offline://resources/");
        dispatchEndServer.Dispatch("game_init");
        dispatchEndServer.Dispatch("login");
        var dispatchEndRule = new LocalDispatchSettlement(10, new[] { 7 }, new[] { new LocalInventoryReward(3, 0, 0, 10000), new LocalInventoryReward(12, 99990, 0, 100) });
        Check(dispatchEndServer.Dispatch("dispatch_end", arguments: new(90, DispatchSettlement: dispatchEndRule with { MemoIds = Array.Empty<int>() })).Status == 503 && dispatchEndServer.Dispatch("dispatch_end", arguments: new(90, DispatchSettlement: dispatchEndRule with { Rewards = new[] { dispatchEndRule.Rewards[0], dispatchEndRule.Rewards[1] with { Capacity = 2 } } })).Status == 409 && dispatchEndServer.Dispatch("login").Body!["user"]!["gold"]!.GetValue<int>() == 5000, "dispatch settlement validates memo definitions and rolls back rewards on capacity failure");
        var dispatchEnded = dispatchEndServer.Dispatch("dispatch_end", arguments: new(90, DispatchSettlement: dispatchEndRule)).Body!;
        Check(dispatchEnded["remove_user_dispatch_id"]!.GetValue<long>() == 90 && dispatchEnded["reward"]!.AsArray().Count == 2 && dispatchEnded["result"]![0]!["performance"]!.GetValue<int>() == 1 && dispatchEnded["user_update"]!["gold"]!.GetValue<int>() == 5100 && dispatchEnded["user_update"]!["dispatch"]!["dispatch_list"]!.AsArray().Count == 0, "dispatch settlement grants its configured outcome and removes the completed task");
        var dispatchEndReload = new OfflineServer(new JsonStateStore(dispatchEndDirectory), seed, "offline://resources/");
        dispatchEndReload.Dispatch("game_init");
        dispatchEndReload.Dispatch("login");
        Check(dispatchEndReload.Dispatch("dispatch_end", arguments: new(90, DispatchSettlement: dispatchEndRule)).Status == 404 && dispatchEndReload.Dispatch("get_dispatch_list").Body!["dispatch_list"]!.AsArray().Count == 0, "dispatch settlement persists and cannot grant or restart the consumed offer again");
        dispatchEndSeed["dispatch"]!["dispatch_list"]![0]!["end_time"] = "2999-01-01 00:00:00";
        var unfinishedDispatch = new OfflineServer(new JsonStateStore(directory + "-dispatch-unfinished"), dispatchEndSeed.ToJsonString(), "offline://resources/");
        unfinishedDispatch.Dispatch("game_init");
        unfinishedDispatch.Dispatch("login");
        Check(unfinishedDispatch.Dispatch("dispatch_end", arguments: new(90, DispatchSettlement: dispatchEndRule)).Status == 409, "dispatch cannot settle before its finish time");
        Console.WriteLine("Passed 4 dispatch settlement checks.");
        var retrySeed = JsonNode.Parse(seed)!;
        retrySeed["retry_gacha_count"] = new JsonArray(new JsonObject { ["gacha_id"] = 20, ["event_id"] = 0, ["total_count"] = 3, ["count"] = 1, ["object_type"] = 9, ["object_id"] = 1001, ["is_fix"] = 0 });
        var retryDirectory = directory + "-retry-confirm";
        var retryServer = new OfflineServer(new JsonStateStore(retryDirectory), retrySeed.ToJsonString(), "offline://resources/");
        retryServer.Dispatch("game_init");
        retryServer.Dispatch("login");
        var retryRule = new LocalRetryFix(20, 1001, 10, true);
        Check(retryServer.Dispatch("retry_gacha_fix", arguments: new(Value: 20, RetryFix: retryRule with { Active = false })).Status == 1006 && retryServer.Dispatch("retry_gacha_fix", arguments: new(Value: 20, RetryFix: retryRule with { Capacity = 1 })).Status == 409 && retryServer.Dispatch("login").Body!["user"]!["retry_gacha_count"]![0]!["is_fix"]!.GetValue<int>() == 0, "retry confirmation preserves the pending selection when expired or over capacity");
        var retryFixed = retryServer.Dispatch("retry_gacha_fix", arguments: new(Value: 20, RetryFix: retryRule)).Body!;
        Check(retryFixed["unique_id"]!.GetValue<long>() == 2 && retryFixed["user_update"]!["unit"]!["unit_list"]!.AsArray().Count == 2 && retryFixed["user_update"]!["retry_gacha_count"]![0]!["is_fix"]!.GetValue<int>() == 1 && retryFixed["user_update"]!["album"]!["unit_list"]!.AsArray().Count == 1, "retry confirmation grants a real instance and persists selection and album state");
        var retryReload = new OfflineServer(new JsonStateStore(retryDirectory), seed, "offline://resources/");
        retryReload.Dispatch("game_init");
        retryReload.Dispatch("login");
        var retryReceipt = retryReload.Dispatch("retry_gacha_fix", arguments: new(Value: 20)).Body!;
        Check(retryReceipt["unique_id"]!.GetValue<long>() == 2 && retryReceipt["user_update"]!["unit"]!["unit_list"]!.AsArray().Count == 2 && retryReload.Dispatch("retry_gacha_fix", arguments: new(Value: 21, RetryFix: retryRule)).Status == 404, "retry confirmation returns the original receipt after restart and rejects unrelated selections");
        Console.WriteLine("Passed 3 retry confirmation checks.");
        var historyPlayerSeed = JsonNode.Parse(seed)!;
        historyPlayerSeed["_local_history_players"] = new JsonArray(new JsonObject { ["player_id"] = "local-profile", ["unit_id"] = 1001, ["costume_id"] = 100101, ["home_motion"] = 0, ["unit_get_count"] = 5, ["quest_complete_count"] = 12, ["dispatch_complete_count"] = 3, ["selected_achievement_id"] = 0, ["bronze_trophy_count"] = 1, ["silver_trophy_count"] = 0, ["gold_trophy_count"] = 0, ["comment"] = "local", ["last_login_at"] = "2026-01-01 00:00:00", ["player_name"] = "local profile", ["player_level"] = 10, ["friend_status"] = 0 });
        var historyPlayerServer = new OfflineServer(new JsonStateStore(directory + "-history-player"), historyPlayerSeed.ToJsonString(), "offline://resources/");
        historyPlayerServer.Dispatch("game_init");
        historyPlayerServer.Dispatch("login");
        Check(historyPlayerServer.Dispatch("get_clear_history_playerinfo", arguments: new(Text: "missing", HistoryDefinitions: historyDefinitions)).Status == 404 && historyPlayerServer.Dispatch("get_clear_history_playerinfo", arguments: new(Text: "local-profile", HistoryDefinitions: historyDefinitions with { Costumes = new() })).Status == 503, "player history rejects unknown players and unavailable avatar definitions");
        var historyPlayerReply = historyPlayerServer.Dispatch("get_clear_history_playerinfo", arguments: new(Text: "local-profile", HistoryDefinitions: historyDefinitions)).Body!;
        Check(historyPlayerReply["player_level"]!.GetValue<int>() == 10 && historyPlayerReply["unit_get_count"]!.GetValue<int>() == 5 && historyPlayerReply["bronze_trophy_count"]!.GetValue<int>() == 1 && !historyPlayerReply.ContainsKey("player_id"), "player history returns the saved profile and counters without unrelated fields");
        historyPlayerReply["unit_get_count"] = 999;
        Check(historyPlayerServer.Dispatch("get_clear_history_playerinfo", arguments: new(Text: "local-profile", HistoryDefinitions: historyDefinitions)).Body!["unit_get_count"]!.GetValue<int>() == 5, "player history returns an independent snapshot");
        Console.WriteLine("Passed 3 player history checks.");
        var friendHistoryReply = historyPlayerServer.Dispatch("friend_get_history", arguments: new(Text: "local-profile", HistoryDefinitions: historyDefinitions)).Body!;
        Check(friendHistoryReply["unit_get_count"]!.GetValue<int>() == 5 && friendHistoryReply["bronze_trophy_count"]!.GetValue<int>() == 1 && !friendHistoryReply.ContainsKey("player_name") && historyPlayerServer.Dispatch("friend_get_history", arguments: new(Text: "missing", HistoryDefinitions: historyDefinitions)).Status == 404, "friend history returns only stored summary fields and rejects missing profiles");
        Console.WriteLine("Passed 1 friend history check.");
        var recoverySeed = JsonNode.Parse(seed)!;
        recoverySeed["_local_tower_recovery_count"] = 3;
        recoverySeed["crystal"] = 10;
        recoverySeed["unit"]!["tower_unit_list"] = new JsonArray(new JsonObject { ["user_unit_id"] = 1L });
        var recoveryDirectory = directory + "-tower-recovery";
        var recoveryServer = new OfflineServer(new JsonStateStore(recoveryDirectory), recoverySeed.ToJsonString(), "offline://resources/");
        recoveryServer.Dispatch("game_init");
        recoveryServer.Dispatch("login");
        var recoveredUnits = recoveryServer.Dispatch("tower_unit_recovery").Body!;
        Check(recoveredUnits["result"]!.GetValue<int>() == 1 && recoveredUnits["remaining_recovery_count"]!.GetValue<int>() == 2 && recoveredUnits["user_update"]!["crystal"]!.GetValue<int>() == 5 && recoveredUnits["user_update"]!["unit"]!["tower_unit_list"]!.AsArray().Count == 0, "recovery clears persisted damage and atomically consumes currency and allowance");
        var recoveryReload = new OfflineServer(new JsonStateStore(recoveryDirectory), seed, "offline://resources/");
        recoveryReload.Dispatch("game_init");
        recoveryReload.Dispatch("login");
        Check(recoveryReload.Dispatch("tower_unit_recovery").Body!["result"]!.GetValue<int>() == 0 && recoveryReload.Dispatch("tower_top").Body!["remaining_recovery_count"]!.GetValue<int>() == 2 && recoveryReload.Dispatch("login").Body!["user"]!["crystal"]!.GetValue<int>() == 5, "repeated recovery after restart cannot charge again for cleared damage");
        recoverySeed["crystal"] = 0;
        var recoveryNoFunds = new OfflineServer(new JsonStateStore(directory + "-tower-no-funds"), recoverySeed.ToJsonString(), "offline://resources/");
        recoveryNoFunds.Dispatch("game_init");
        recoveryNoFunds.Dispatch("login");
        Check(recoveryNoFunds.Dispatch("tower_unit_recovery").Body!["result"]!.GetValue<int>() == 0 && recoveryNoFunds.Dispatch("login").Body!["user"]!["unit"]!["tower_unit_list"]!.AsArray().Count == 1, "insufficient recovery funds preserve damage and allowance");
        Console.WriteLine("Passed 3 recovery checks.");
    }
}
